import pandas as pd


def apply(df, ctx):
    out = df.copy()
    out["skin_tone"] = out[["rater1", "rater2"]].mean(axis=1, skipna=False)
    keep = (out["skin_tone"] <= 0.25) | (out["skin_tone"] >= 0.75)
    return out[keep].copy()
